"""Generated Experience-owned APIs 114/115/116/136."""
from authorization import REF, UUID, VERSION, object_schema, operation, parameter

def extend_experience(spec):
    schemas=spec['components']['schemas'];paths=spec['paths']
    key=parameter('Idempotency-Key','header',{'type':'string','minLength':1,'maxLength':100,'pattern':r'^[ -~]+$'},True)
    match=parameter('If-Match','header',{'type':'string','pattern':r'^"(0|[1-9][0-9]{0,18})"$'},True)
    path=parameter('id','path',UUID,True)
    schemas['ExperienceFileUploadInput']=object_schema({'purpose':{'enum':['IMAGE','BROCHURE','DISTRIBUTOR_PROOF']},'filename':{'type':'string','minLength':1,'maxLength':120},'mimeType':{'enum':['image/jpeg','image/png','image/webp','application/pdf']},'size':{'type':'integer','format':'int64','minimum':1,'maximum':10485760},'checksumSha256':{'type':'string','pattern':'^[a-f0-9]{64}$'},'linkedResourceId':UUID})
    schemas['ExperienceFileUploadInput']['required']=['purpose','filename','mimeType','size','checksumSha256']
    schemas['ExperienceFileUploadResult']=object_schema({'assetId':UUID,'uploadUrl':{'type':'string','format':'uri','pattern':'^https:'},'requiredHeaders':{'type':'object','maxProperties':20,'propertyNames':{'type':'string','maxLength':100},'additionalProperties':{'type':'string','maxLength':2048}},'expiresAt':{'type':'string','format':'date-time'}})
    schemas['ExperienceFileAsset']=object_schema({'id':UUID,'state':{'enum':['UPLOADING','QUARANTINED','CLEAN','REJECTED']},'purpose':{'enum':['IMAGE','BROCHURE','DISTRIBUTOR_PROOF']},'mimeType':{'type':'string','maxLength':100},'size':{'type':'integer','format':'int64','minimum':1},'checksum':{'type':'string','pattern':'^[a-f0-9]{64}$'},'url':{'type':['string','null'],'format':'uri'},'version':VERSION})
    schemas['ExperienceFileDownload']=object_schema({'url':{'type':'string','format':'uri','pattern':'^https:'},'expiresAt':{'type':'string','format':'date-time'}})
    schemas['ExperienceFileScanResult']=object_schema({'commandId':UUID,'checksumSha256':{'type':'string','pattern':'^[a-f0-9]{64}$'},'result':{'enum':['CLEAN','REJECTED']},'scannerVersion':{'type':'string','minLength':1,'maxLength':100},'reasonCode':{'type':'string','pattern':'^[A-Z][A-Z0-9_]{0,99}$'}})
    schemas['ExperienceFileScanResult']['required']=['commandId','checksumSha256','result','scannerVersion']
    upload=operation('API-114','Experience owner. Signed current actor; CONTENT_EDITOR may upload IMAGE/BROCHURE and the matching CUSTOMER may upload PRIVATE DISTRIBUTOR_PROOF. Original filename is display-only; UUID owner/resource/purpose and checksum bind the quarantine object. Idempotent create returns a five-minute constrained HTTPS upload capability; no final URI is exposed.', 'ExperienceFileUploadResult',[key]);upload['security']=[{'workload':['files.upload_WITH_SIGNED_ACTOR'],'signedActor':[]}];upload['requestBody']={'required':True,'content':{'application/json':{'schema':REF('ExperienceFileUploadInput')}}};upload['responses']['201']=upload['responses'].pop('200');upload['responses']['201']['headers']={'Cache-Control':{'schema':{'const':'no-store'}},'ETag':{'schema':{'const':'"0"'}}}
    complete=operation('API-115','Experience owner. Exact signed actor scope, creator/resource/purpose authorization and If-Match. Verify quarantine HEAD outside the transaction (owner, size, MIME, encryption, SHA-256, immutable version/ETag); atomically persist QUARANTINED, audit and EVT-025 file.scan.requested.v1 in the Experience outbox. Idempotent replay returns the original response.', 'ExperienceFileAsset',[path,match,key]);complete['security']=[{'workload':['files.complete_WITH_SIGNED_ACTOR'],'signedActor':[]}];complete['requestBody']={'required':True,'content':{'application/json':{'schema':object_schema({'checksumSha256':{'type':'string','pattern':'^[a-f0-9]{64}$'}})}}};complete['responses']['202']=complete['responses'].pop('200');complete['responses']['202']['headers']={'Cache-Control':{'schema':{'const':'no-store'}},'ETag':{'schema':{'type':'string'}}}
    download=operation('API-116','Experience owner. Authenticated, purpose- and owner/resource-authorized clean asset only. CUSTOMER reads only their PRIVATE business proof; CONTENT_EDITOR reads only Experience media permitted by current owner policy. Reject quarantined/rejected assets. Return a private, short-lived HTTPS capability with no-store.', 'ExperienceFileDownload',[path]);download['security']=[{'workload':['files.download_WITH_SIGNED_ACTOR'],'signedActor':[]}]
    scan=operation('API-136','Exact nigson-integration files.scan.write workload only; no browser/caller actor. commandId and checksum must match this Experience asset’s EVT-025 request. CLEAN promotion is pinned to the verified quarantine object version and occurs outside transactions. Timeout remains UNKNOWN and is reconciled by final-object HEAD; no blind retry or terminal reversal.', 'ExperienceFileAsset',[path,match,key]);scan['security']=[{'workload':['files.scan.write']}];scan['requestBody']={'required':True,'content':{'application/json':{'schema':REF('ExperienceFileScanResult')}}};scan['responses']['200']['headers']={'Cache-Control':{'schema':{'const':'no-store'}},'ETag':{'schema':{'type':'string'}}};scan['responses']['503']={'description':'Provider unavailable or uncertain; keep UNKNOWN and reconcile without blind promotion retry'}
