    scopes=spec['components']['securitySchemes']['workload']['flows']['clientCredentials']['scopes'];scopes.update({'files.upload_WITH_SIGNED_ACTOR':'Create an Experience-owned purpose-authorized upload','files.complete_WITH_SIGNED_ACTOR':'Complete and quarantine an Experience-owned upload','files.download_WITH_SIGNED_ACTOR':'Download an authorized clean Experience file'})
    return spec
